import React, { forwardRef } from 'react';

import { getAppName } from '@dynatrace-sdk/app-environment';

import { Text } from '../../typography/Text.js';

/**
 * The `AppName` component retrieves the name of the app using the Dynatrace SDK and renders it as `Text`.
 */
export const AppName = /* @__PURE__ */ forwardRef<HTMLDivElement>(
  (_, forwardedRef) => {
    const appName = getAppName?.() || '';

    return (
      <Text as="div" ref={forwardedRef} textStyle="base-emphasized">
        {appName}
      </Text>
    );
  },
);

(AppName as typeof AppName & { displayName: string }).displayName = 'AppName';
